function product_slug(string $name): string { return trim(strtolower((string)preg_replace('/[^a-z0-9]+/i','-',$name)),'-'); }
function save_product_image(array $file, int $productId): bool {
    if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK || ($file['size']??0)>8*1024*1024) return false;
    $info=@getimagesize($file['tmp_name']); if(!$info) return false;
    $type=$info[2];$extension=match($type){IMAGETYPE_JPEG=>'jpg',IMAGETYPE_PNG=>'png',IMAGETYPE_WEBP=>'webp',default=>null};
    if(defined('IMAGETYPE_AVIF')&&$type===IMAGETYPE_AVIF)$extension='avif';if(!$extension)return false;
    $canConvert=function_exists('imagewebp')&&(!defined('IMAGETYPE_AVIF')||$type!==IMAGETYPE_AVIF||function_exists('imagecreatefromavif'));
    $name='product-'.bin2hex(random_bytes(10)).'.'.($canConvert?'webp':$extension);$path=UPLOAD_DIR.$name;$source=null;
    if($canConvert){$source=match($type){IMAGETYPE_JPEG=>@imagecreatefromjpeg($file['tmp_name']),IMAGETYPE_PNG=>@imagecreatefrompng($file['tmp_name']),IMAGETYPE_WEBP=>function_exists('imagecreatefromwebp')?@imagecreatefromwebp($file['tmp_name']):null,default=>null};if(defined('IMAGETYPE_AVIF')&&$type===IMAGETYPE_AVIF&&function_exists('imagecreatefromavif'))$source=@imagecreatefromavif($file['tmp_name']);}
    $saved=$source?imagewebp($source,$path,84):move_uploaded_file($file['tmp_name'],$path);if($source)imagedestroy($source);if(!$saved||!is_file($path))return false;
    $max=db()->prepare('SELECT COALESCE(MAX(sort_order),0) FROM product_images WHERE product_id=?');$max->execute([$productId]);$url=base('uploads/'.$name);
    db()->prepare('INSERT INTO product_images(product_id,image_url,sort_order) VALUES(?,?,?)')->execute([$productId,$url,(int)$max->fetchColumn()+1]);db()->prepare('UPDATE products SET image=COALESCE(NULLIF(image,\'\'),?) WHERE id=?')->execute([$url,$productId]);return true;
}
