 $id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['slug'])?:product_slug(trim($_POST['name'])),$_POST['category_id']?:null,trim($_POST['sku']),trim($_POST['barcode']),$_POST['price'],$_POST['old_price']?:null,max(0,(int)$_POST['stock']),trim($_POST['color']),trim($_POST['sizes']),trim($_POST['description']),$_POST['status'],isset($_POST['featured'])?1:0];
 try{if($id){db()->prepare('UPDATE products SET name=?,slug=?,category_id=?,sku=?,barcode=?,price=?,old_price=?,stock=?,color=?,sizes=?,description=?,status=?,featured=? WHERE id=?')->execute([...$data,$id]);}else{db()->prepare('INSERT INTO products(name,slug,category_id,sku,barcode,price,old_price,stock,color,sizes,description,status,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)db()->lastInsertId();}
   foreach($_FILES['images']['tmp_name']??[] as $i=>$tmp)save_product_image(['tmp_name'=>$tmp,'error'=>$_FILES['images']['error'][$i],'size'=>$_FILES['images']['size'][$i]],$id); flash('success','تم حفظ المنتج والصور بنجاح.');
 }catch(Throwable $e){flash('error','تعذر الحفظ. تأكد من أن الرابط المختصر وSKU غير مكررين.');}
 header('Location: '.base('admin/products.php?edit='.$id));exit;
}
